                Abc_Print( -1, "Command line switch \"-T\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.TimeLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.TimeLimit < 0 {
                goto usage; }
            break;
        case 'B':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-B\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nBddMax = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nBddMax < 0 {
