/**Function*************************************************************

  Synopsis    []

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Abc_FrameReplaceCex(pAbc *Abc_Frame_t, ppCex **Abc_Cex_t) {
    // update CEX
    ABC_FREE( pAbc.pCex );
    pAbc.pCex = *ppCex;
    *ppCex = nil;
    // remove CEX vector
    if pAbc.vCexVec {
        Vec_PtrFreeFree( pAbc.vCexVec );
        pAbc.vCexVec = nil;
    }
}

/**Function*************************************************************

  Synopsis    []

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Abc_FrameReplaceCexVec(pAbc *Abc_Frame_t, pvCexVec **Vec_Ptr_t) {
    // update CEX vector
    if pAbc.vCexVec {
        Vec_PtrFreeFree( pAbc.vCexVec ); }
    pAbc.vCexVec = *pvCexVec;
    *pvCexVec = nil;
    // remove CEX
    ABC_FREE( pAbc.pCex );
}

