/**Function*************************************************************

  Synopsis    [Derives array of statuses from the array of CEXes.]

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Abc_FrameDeriveStatusArray(vCexes *Vec_Ptr_t) *Vec_Int_t {
    var vStatuses *Vec_Int_t;
    var pCex *Abc_Cex_t;
    var i int32;
    if vCexes == nil {
        return nil; }
    vStatuses = Vec_IntAlloc( Vec_PtrSize(vCexes) );
    Vec_IntFill( vStatuses, Vec_PtrSize(vCexes), -1 ); // assume UNDEC
    Vec_PtrForEachEntry( Abc_Cex_t *, vCexes, pCex, i )
        if ( pCex != nil )
            Vec_IntWriteEntry( vStatuses, i, 0 ); // set this output as SAT
    return vStatuses;
}
func Abc_FrameDeriveStatusArray2(vCexes *Vec_Ptr_t) *Vec_Int_t {
    var vStatuses *Vec_Int_t;
    var pCex *Abc_Cex_t;
    var i int32;
    if vCexes == nil {
        return nil; }
    vStatuses = Vec_IntAlloc( Vec_PtrSize(vCexes) );
    Vec_IntFill( vStatuses, Vec_PtrSize(vCexes), -1 ); // assume UNDEC
    Vec_PtrForEachEntry( Abc_Cex_t *, vCexes, pCex, i )
        if pCex == (Abc_Cex_t *)(ABC_PTRINT_T)1 {
            Vec_IntWriteEntry( vStatuses, i, 1 ); // set this output as UNSAT
            Vec_PtrWriteEntry( vCexes, i, nil );

        } else if pCex != nil {
            Vec_IntWriteEntry( vStatuses, i, 0 ); } // set this output as SAT
    return vStatuses;
}

