func AbcCommandDispatchById(Id Cmd_CommandId_t, pAbc *Abc_Frame_t, argc int32, argv *string, pResult *int32) int32 {
    switch  Id  {
    case CMD_COMMAND_STRASH:
        *pResult = Abc_CommandStrash( pAbc, argc, argv );
        return 1;
    case CMD_COMMAND_PRINT_STATS:
        *pResult = Abc_CommandPrintStats( pAbc, argc, argv );
        return 1;
    case CMD_COMMAND_PDR:
        *pResult = Abc_CommandPdr( pAbc, argc, argv );
        return 1;
    default:
        return 0;
    }
}

