        default:
            goto usage;
        }
    }

    if pNtk == nil {
        Abc_Print( -1, "Empty network.\n" );
        return 1;
    }

    // print support information
    if fStruct != 0 {
        Abc_NtkPrintStrSupports( pNtk, fVeryVerbose );
        return 0;
