func Abc_CommandPrintStatus(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    extern void Abc_NtkDumpOneCexSpecial( FILE * pFile, Abc_Ntk_t * pNtk, Abc_Cex_t * pCex );
    extern void Abc_NtkPrintPoEquivs( Abc_Ntk_t * pNtk );
