    }
    if fOutStatus != 0 {
        if pNtk == nil {
            Abc_Print( -1, "Empty network.\n" );
            return 1;
        }
        Abc_NtkPrintPoEquivs( pNtk );
        return 0;
    }
    if !pAbc.vStatuses {
        Abc_Print( 1,"Status = %d  Frames = %d   ", pAbc.Status, pAbc.nFrames ); }
    if pAbc.pCex == nil && pAbc.vCexVec == nil {
        Abc_Print( 1,"Cex is not defined.\n" );
    } else {
        if pAbc.pCex {
            Abc_CexPrintStats( pAbc.pCex ); }
        if pAbc.vCexVec {
            var pTemp *Abc_Cex_t;
            var nCexes int32;
            var Counter int32;
            //printf( "\n" );
            Vec_PtrForEachEntry( Abc_Cex_t *, pAbc.vCexVec, pTemp, c )
            {
                if pTemp == (void *)(ABC_PTRINT_T)1 {
                    Counter++;
                    continue;
                }
                if pTemp {
                    fmt.Printf("%4d : ", ++nCexes);
                    Abc_CexPrintStats( pTemp );
                }
            }
//            if ( Counter )
//                printf( "In total, %d (out of %d) outputs are \"sat\" but CEXes are not recorded.\n", Counter, Vec_PtrSize(pAbc->vCexVec) );
        }
    }
    if pAbc.vStatuses {
        if pLogFileName {
            var pTemp *Abc_Cex_t  = nil;
            var pFile *os.File  = os.OpenFile(pLogFileName, os.O_WRONLY | os.O_CREATE | os.O_TRUNC, 0666);
            if pFile == nil {
                fmt.Printf("Cannot open file \"%s\" for writing.\n", pLogFileName);
                return 0;
            }
            Vec_PtrForEachEntry( Abc_Cex_t *, pAbc.vCexVec, pTemp, c )
            {
                var Status int32  = Vec_IntEntry( pAbc.vStatuses, c );
                if Status == -1 { // undec
                    fmt.Fprintf(pFile, "STATUS: ABORTED ");
                } else if Status == 0 {
                    fmt.Fprintf(pFile, "STATUS: SAT ");
                } else if Status == 1 {
                    fmt.Fprintf(pFile, "STATUS: UNSAT "); }
                fmt.Fprintf(pFile, "%s\n", Abc_ObjName(Abc_NtkPo(pNtk, c)));
                if Status != 0 {
                    continue; }
                Abc_NtkDumpOneCexSpecial( pFile, pNtk, pTemp );
            }
            _ = (pFile).Close();

        } else if fShort != 0 {
            fmt.Printf("Status array contains %d SAT, %d UNSAT, and %d UNDEC entries (out of %d).", Vec_IntCountEntry(pAbc.vStatuses, 0), Vec_IntCountEntry(pAbc.vStatuses, 1), Vec_IntCountEntry(pAbc.vStatuses, -1), Vec_IntSize(pAbc.vStatuses));

        } else {
            var i, Entry int32;
            Vec_IntForEachEntry( pAbc.vStatuses, Entry, i )
                fmt.Printf("%d=%d  ", i, Entry);
        }
        fmt.Printf("\n");
    }
    return 0;

usage:
    Abc_Print( -2, "usage: print_status [-L file] [-osh]\n" );
    Abc_Print( -2, "\t          prints verification status\n" );
    Abc_Print( -2, "\t-L file : the log file name [default = %s]\n",  pLogFileName ? pLogFileName : "no logging" );
    Abc_Print( -2, "\t-o      : toggle printing output status [default = %s]\n", fOutStatus? "yes": "no" );
    Abc_Print( -2, "\t-s      : toggle using short print-out [default = %s]\n", fShort? "yes": "no" );
    Abc_Print( -2, "\t-h      : print the command usage\n");
    return 1;
}

/**Function*************************************************************

  Synopsis    []

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Abc_CommandPrintDelay(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    var pNtk *Abc_Ntk_t  = Abc_FrameReadNtk(pAbc);
    var pObjIn *Abc_Obj_t = nil;
    var pObjOut *Abc_Obj_t = nil;
    var c int32;
    // set defaults
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "h" ) ) != -1  {
        switch  c  {
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    if pNtk == nil {
        Abc_Print( -1, "Empty network.\n" );
        return 1;
    }
    if !Abc_NtkIsMappedLogic(pNtk) {
        Abc_Print( -1, "Delay trace works only for network mapped into standard cells.\n" );
        return 1;
    }
    if argc > globalUtilOptind + 2 {
        Abc_Print( -1, "Wrong number of auguments.\n" );
        goto usage;
    }
    // collect the first name (PO name)
    if argc >= globalUtilOptind + 1 {
        var Num int32  = Nm_ManFindIdByName( pNtk.pManName, argv[globalUtilOptind], ABC_OBJ_PO );
        if Num < 0 {
            Num = Nm_ManFindIdByName( pNtk.pManName, argv[globalUtilOptind], ABC_OBJ_BI ); }
        if Num >= 0 {
            pObjOut = Abc_NtkObj( pNtk, Num ); }
        if pObjOut == nil {
            Abc_Print( 1, "Cannot find combinational output \"%s\".\n", argv[globalUtilOptind] );
            return 1;
        }
    }
    // collect the second name (PI name)
    if argc == globalUtilOptind + 2 {
        var Num int32  = Nm_ManFindIdByName( pNtk.pManName, argv[globalUtilOptind+1], ABC_OBJ_PI );
        if Num < 0 {
            Num = Nm_ManFindIdByName( pNtk.pManName, argv[globalUtilOptind+1], ABC_OBJ_BO ); }
        if Num >= 0 {
            pObjIn = Abc_NtkObj( pNtk, Num ); }
        if pObjIn == nil {
            Abc_Print( 1, "Cannot find combinational input \"%s\".\n", argv[globalUtilOptind+1] );
            return 1;
        }
    }
    Abc_NtkDelayTrace( pNtk, pObjOut, pObjIn, 1 );
    return 0;

usage:
    Abc_Print( -2, "usage: print_delay [-h] <CO_name> <CI_name>\n" );
    Abc_Print( -2, "\t            prints one critical path of the mapped network\n" );
    Abc_Print( -2, "\t-h        : print the command usage\n");
    Abc_Print( -2, "\t<CO_name> : (optional) the sink of the critical path (primary output or flop input)\n");
    Abc_Print( -2, "\t<CI_name> : (optional) the source of the critical path (primary input or flop output)\n");
    Abc_Print( -2, "\t            (if CO and/or CI are not given, uses the most critical ones)\n");
    return 1;
}

