***********************************************************************/
func Abc_CommandSatClp(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    var pNtk *Abc_Ntk_t = Abc_FrameReadNtk(pAbc);
    var pNtkRes *Abc_Ntk_t;
    var nCubeLim int32;
    var nBTLimit int32    =  1000000;
    var nCostMax int32    = 20000000;
    var fCanon int32;
    var fReverse int32;
    var fCnfShared int32;
    var fVerbose int32;
    var c int32;

    // set defaults
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "CLZcrsvh" ) ) != -1  {
        switch  c  {
        case 'C':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-C\" should be followed by an integer.\n" );
                goto usage;
            }
            nCubeLim = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nCubeLim < 0 {
                goto usage; }
            break;
        case 'L':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-L\" should be followed by an integer.\n" );
                goto usage;
            }
            nBTLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nBTLimit < 0 {
                goto usage; }
            break;
        case 'Z':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-Z\" should be followed by an integer.\n" );
                goto usage;
            }
            nCostMax = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nCostMax < 0 {
                goto usage; }
            break;
        case 'c':
            fCanon ^= 1;
            break;
        case 'r':
            fReverse ^= 1;
            break;
        case 's':
            fCnfShared ^= 1;
            break;
        case 'v':
            fVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }

    if pNtk == nil {
        Abc_Print( -1, "Empty network.\n" );
        return 1;
    }

    if !Abc_NtkIsLogic(pNtk) && !Abc_NtkIsStrash(pNtk) {
        Abc_Print( -1, "Can only collapse a logic network or an AIG.\n" );
        return 1;
    }

    // get the new network
    if Abc_NtkIsStrash(pNtk) {
        pNtkRes = Abc_NtkCollapseSat( pNtk, nCubeLim, nBTLimit, nCostMax, fCanon, fReverse, fCnfShared, fVerbose );
    } else {
        pNtk = Abc_NtkStrash( pNtk, 0, 0, 0 );
        pNtkRes = Abc_NtkCollapseSat( pNtk, nCubeLim, nBTLimit, nCostMax, fCanon, fReverse, fCnfShared, fVerbose );
        Abc_NtkDelete( pNtk );
    }
    if pNtkRes == nil {
        Abc_Print( -1, "Collapsing has failed.\n" );
        return 0;
    }
    // replace the current network
    Abc_FrameReplaceCurrentNetwork( pAbc, pNtkRes );
    return 0;

usage:
    Abc_Print( -2, "usage: satclp [-CLZ num] [-crsvh]\n" );
    Abc_Print( -2, "\t         performs SAT based collapsing\n" );
    Abc_Print( -2, "\t-C num : the limit on the SOP size of one output [default = %d]\n",              nCubeLim );
    Abc_Print( -2, "\t-L num : the limit on the number of conflicts in one SAT call [default = %d]\n", nBTLimit );
    Abc_Print( -2, "\t-Z num : the limit on the cost of the largest output [default = %d]\n",          nCostMax );
    Abc_Print( -2, "\t-c     : toggles using canonical ISOP computation [default = %s]\n",             fCanon? "yes": "no" );
    Abc_Print( -2, "\t-r     : toggles using reverse veriable ordering [default = %s]\n",              fReverse? "yes": "no" );
