    Abc_Print( -2, "\t-h       : print the command usage\n");
    return 1;
}

/**Function*************************************************************

  Synopsis    []

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Abc_CommandMfs2(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    extern int Abc_NtkPerformMfs( Abc_Ntk_t * pNtk, Sfm_Par_t * pPars );
    extern int Abc_NtkMfsAfterICheck( Abc_Ntk_t * p, int nFrames, int nFramesAdd, Vec_Int_t * vFlops, Sfm_Par_t * pPars );
    var pNtk *Abc_Ntk_t  = Abc_FrameReadNtk(pAbc);
    var Pars Sfm_Par_t;
    var pPars *Sfm_Par_t = &Pars;
    var c, fIndDCs, fUseAllFfs, nFramesAdd int32;
    // set defaults
    Sfm_ParSetDefault( pPars );
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "WFDMLCZNIdaeijlvwh" ) ) != -1  {
        switch  c  {
        case 'W':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-W\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nTfoLevMax = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nTfoLevMax < 0 {
                goto usage; }
            break;
        case 'F':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-F\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nFanoutMax = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nFanoutMax < 0 {
                goto usage; }
            break;
        case 'D':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-D\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nDepthMax = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nDepthMax < 0 {
                goto usage; }
            break;
        case 'M':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-M\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nWinSizeMax = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nWinSizeMax < 0 {
                goto usage; }
            break;
        case 'L':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-L\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nGrowthLevel = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nGrowthLevel < -ABC_INFINITY || pPars.nGrowthLevel > ABC_INFINITY {
                goto usage; }
            break;
        case 'C':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-C\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nBTLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nBTLimit < 0 {
                goto usage; }
            break;
        case 'Z':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-Z\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nFirstFixed = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nFirstFixed < 0 {
                goto usage; }
            break;
        case 'N':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-N\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nNodesMax = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nNodesMax < 0 {
                goto usage; }
            break;
        case 'I':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-I\" should be followed by an integer.\n" );
                goto usage;
            }
            nFramesAdd = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nFramesAdd < 0 {
                goto usage; }
            break;
        case 'd':
            pPars.fRrOnly ^= 1;
            break;
        case 'a':
            pPars.fArea ^= 1;
            break;
        case 'e':
            pPars.fMoreEffort ^= 1;
            break;
        case 'i':
            fIndDCs ^= 1;
            break;
        case 'j':
            fUseAllFfs ^= 1;
            break;
        case 'l':
            pPars.fUseDcs ^= 1;
            break;
        case 'v':
            pPars.fVerbose ^= 1;
            break;
        case 'w':
            pPars.fVeryVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    if pNtk == nil {
        Abc_Print( -1, "Empty network.\n" );
        return 1;
    }
    if !Abc_NtkIsLogic(pNtk) {
        Abc_Print( -1, "This command can only be applied to a logic network.\n" );
        return 1;
    }
    if fIndDCs {
        if fUseAllFfs {
            pAbc.nIndFrames = 1;
            Vec_IntFreeP( &pAbc.vIndFlops );
            pAbc.vIndFlops = Vec_IntAlloc( Abc_NtkLatchNum(pNtk) );
            Vec_IntFill( pAbc.vIndFlops, Abc_NtkLatchNum(pNtk), 1 );
        }
        if pAbc.nIndFrames <= 0 {
            Abc_Print( -1, "The number of k-inductive frames is not specified.\n" );
            return 0;
        }
        if pAbc.vIndFlops == nil {
            Abc_Print( -1, "The set of k-inductive flops is not specified.\n" );
            return 0;
        }
        if Vec_IntSize(pAbc.vIndFlops) != Abc_NtkLatchNum(pNtk) {
            Abc_Print( -1, "The saved flop count (%d) does not match that of the current network (%d).\n",
                Vec_IntSize(pAbc.vIndFlops), Abc_NtkLatchNum(pNtk) );
            return 0;
        }
        // modify the current network
        if !Abc_NtkMfsAfterICheck( pNtk, pAbc.nIndFrames, nFramesAdd, pAbc.vIndFlops, pPars ) {
            Abc_Print( -1, "Resynthesis has failed.\n" );
            return 1;
        }
        if fUseAllFfs {
            pAbc.nIndFrames = 0;
            Vec_IntFreeP( &pAbc.vIndFlops );
        }

    } else {
        // modify the current network
        if !Abc_NtkPerformMfs( pNtk, pPars ) {
            Abc_Print( -1, "Resynthesis has failed.\n" );
            return 1;
        }
    }
    return 0;

usage:
    Abc_Print( -2, "usage: mfs2 [-WFDMLCZNI <num>] [-daeijlvwh]\n" );
    Abc_Print( -2, "\t           performs don't-care-based optimization of logic networks\n" );
    Abc_Print( -2, "\t-W <num> : the number of levels in the TFO cone (0 <= num) [default = %d]\n",             pPars.nTfoLevMax );
    Abc_Print( -2, "\t-F <num> : the max number of fanouts to skip (1 <= num) [default = %d]\n",                pPars.nFanoutMax );
    Abc_Print( -2, "\t-D <num> : the max depth nodes to try (0 = no limit) [default = %d]\n",                   pPars.nDepthMax );
    Abc_Print( -2, "\t-M <num> : the max node count of windows to consider (0 = no limit) [default = %d]\n",    pPars.nWinSizeMax );
    Abc_Print( -2, "\t-L <num> : the max increase in node level after resynthesis (0 <= num) [default = %d]\n", pPars.nGrowthLevel );
    Abc_Print( -2, "\t-C <num> : the max number of conflicts in one SAT run (0 = no limit) [default = %d]\n",   pPars.nBTLimit );
    Abc_Print( -2, "\t-Z <num> : treat the first <num> logic nodes as fixed (0 = none) [default = %d]\n",       pPars.nFirstFixed );
    Abc_Print( -2, "\t-N <num> : the max number of nodes to try (0 = all) [default = %d]\n",                    pPars.nNodesMax );
    Abc_Print( -2, "\t-d       : toggle performing redundancy removal [default = %s]\n",                        pPars.fRrOnly? "yes": "no" );
    Abc_Print( -2, "\t-a       : toggle minimizing area or area+edges [default = %s]\n",                        pPars.fArea? "area": "area+edges" );
    Abc_Print( -2, "\t-e       : toggle high-effort resubstitution [default = %s]\n",                           pPars.fMoreEffort? "yes": "no" );
    Abc_Print( -2, "\t-i       : toggle using inductive don't-cares [default = %s]\n",                          fIndDCs? "yes": "no" );
    Abc_Print( -2, "\t-j       : toggle using all flops when \"-i\" is enabled [default = %s]\n",               fUseAllFfs? "yes": "no" );
    Abc_Print( -2, "\t-I       : the number of additional frames inserted [default = %d]\n",                    nFramesAdd );
    Abc_Print( -2, "\t-l       : toggle deriving don't-cares [default = %s]\n",                                 pPars.fUseDcs? "yes": "no" );
    Abc_Print( -2, "\t-v       : toggle printing optimization summary [default = %s]\n",                        pPars.fVerbose? "yes": "no" );
    Abc_Print( -2, "\t-w       : toggle printing detailed stats for each node [default = %s]\n",                pPars.fVeryVerbose? "yes": "no" );
    Abc_Print( -2, "\t-h       : print the command usage\n");
    return 1;
}

