***********************************************************************/
func Abc_CommandLogicPush(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    extern Abc_Ntk_t * Abc_NtkOptPush( Abc_Ntk_t * pNtk, int nLutSize, int fVerbose );
    var pNtk *Abc_Ntk_t  = Abc_FrameReadNtk(pAbc);
    var pNtkRes *Abc_Ntk_t;
    var nLutSize int32  = 4;
    var fVerbose int32;
    var c int32;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "Kvh" ) ) != -1  {
        switch  c  {
        case 'K':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-K\" should be followed by a positive integer.\n" );
                goto usage;
            }
            nLutSize = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nLutSize < 0 {
                goto usage; }
            break;
        case 'v':
            fVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    if pNtk == nil {
        Abc_Print( -1, "Empty network.\n" );
        return 1;
    }
    if !Abc_NtkIsLogic(pNtk) {
        Abc_Print( -1, "This command can only be applied to a logic network.\n" );
        return 1;
    }
    nLutSize = Abc_MaxInt( nLutSize, Abc_NtkGetFaninMax(pNtk) );
    Abc_NtkToSop( pNtk, -1, ABC_INFINITY );
    pNtkRes = Abc_NtkOptPush( pNtk, nLutSize, fVerbose );
    Abc_FrameReplaceCurrentNetwork( pAbc, pNtkRes );
    return 0;
usage:
    Abc_Print( -2, "usage: logicpush [-K num] [-vh]\n" );
    Abc_Print( -2, "\t           performs logic pushing to reduce structural bias\n" );
    Abc_Print( -2, "\t-K <num> : the LUT size used in the mapping [default = %d]\n", nLutSize );
    Abc_Print( -2, "\t-v       : toggle printing optimization summary [default = %s]\n", fVerbose? "yes": "no" );
    Abc_Print( -2, "\t-h       : print the command usage\n");
    return 1;
}


