func Abc_CommandMajExact(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    extern int Maj_ManExactSynthesis( int nVars, int nNodes, int fUseConst, int fUseLine, int fVerbose );
    extern int Maj_ManExactSynthesis2( int nVars, int nNodes, int fUseConst, int fUseLine, int fUseRand, int nRands, int fVerbose );
    var c int32;
    var nVars int32 = 3;
    var nNodes int32 = 1;
    var fUseConst int32;
    var fUseLine int32;
    var fGlucose int32;
    var fUseRand int32;
    var nRands int32;
    var fVerbose int32 = 1;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "INRfcrgvh" ) ) != -1  {
        switch  c  {
        case 'I':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-I\" should be followed by an integer.\n" );
                goto usage;
            }
            nVars = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nVars < 0 {
                goto usage; }
            break;
        case 'N':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-N\" should be followed by an integer.\n" );
                goto usage;
            }
            nNodes = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nNodes < 0 {
                goto usage; }
            break;
        case 'R':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-R\" should be followed by an integer.\n" );
                goto usage;
            }
            nRands = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nRands < 0 {
                goto usage; }
            break;
        case 'f':
            fUseConst ^= 1;
            break;
        case 'c':
            fUseLine ^= 1;
            break;
        case 'r':
            fUseRand ^= 1;
            break;
        case 'g':
            fGlucose ^= 1;
            break;
        case 'v':
            fVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    if (nVars & 1) == 0 {
        Abc_Print( -1, "Cannot sythesize MAJ gate with an even number of inputs (%d).\n", nVars );
        return 1;
    }
    if fGlucose != 0 {
        Maj_ManExactSynthesis( nVars, nNodes, fUseConst, fUseLine, fVerbose );
    } else {
        Maj_ManExactSynthesis2( nVars, nNodes, fUseConst, fUseLine, fUseRand, nRands, fVerbose ); }
