func Abc_CommandSop(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    var pNtk *Abc_Ntk_t  = Abc_FrameReadNtk(pAbc);
    var c int32;
    var fMode int32 = -1;
    var nCubeLimit int32 = 1000000;

    // set defaults
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "Cdnh" ) ) != -1  {
        switch  c  {
        case 'C':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-C\" should be followed by an integer.\n" );
                goto usage;
            }
            nCubeLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nCubeLimit < 0 {
                goto usage; }
            break;
        case 'd':
            fMode = 1;
            break;
        case 'n':
            fMode = 0;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    if pNtk == nil {
        Abc_Print( -1, "Empty network.\n" );
