func Abc_CommandTestSeqSweep(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    var pFileName string;
    var Pars Fra_Ssw_t;
    var pPars *Fra_Ssw_t = &Pars;
    var c int32;
//    extern Abc_Ntk_t * Abc_NtkDarSeqSweep( Abc_Ntk_t * pNtk, Fra_Ssw_t * pPars );
    extern int Fra_FraigInductionTest( char * pFileName, Fra_Ssw_t * pParams );

    // set defaults
    pPars.nPartSize  = 0;
    pPars.nOverSize  = 0;
    pPars.nFramesP   = 0;
    pPars.nFramesK   = 1;
    pPars.nMaxImps   = 5000;
    pPars.nMaxLevs   = 0;
    pPars.fUseImps   = 0;
    pPars.fRewrite   = 0;
    pPars.fFraiging  = 0;
    pPars.fLatchCorr = 0;
    pPars.fWriteImps = 0;
    pPars.fUse1Hot   = 0;
    pPars.fVerbose   = 0;
    pPars.TimeLimit  = 0;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "PQNFILirfletvh" ) ) != -1  {
        switch  c  {
        case 'P':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-P\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nPartSize = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nPartSize < 2 {
                goto usage; }
            break;
        case 'Q':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-Q\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nOverSize = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nOverSize < 0 {
                goto usage; }
            break;
        case 'N':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-N\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nFramesP = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nFramesP < 0 {
                goto usage; }
            break;
        case 'F':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-F\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nFramesK = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nFramesK <= 0 {
                goto usage; }
            break;
        case 'I':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-I\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nMaxImps = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nMaxImps <= 0 {
                goto usage; }
            break;
        case 'L':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-L\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nMaxLevs = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nMaxLevs <= 0 {
                goto usage; }
            break;
        case 'i':
            pPars.fUseImps ^= 1;
            break;
        case 'r':
            pPars.fRewrite ^= 1;
            break;
        case 'f':
            pPars.fFraiging ^= 1;
            break;
        case 'l':
            pPars.fLatchCorr ^= 1;
            break;
        case 'e':
            pPars.fWriteImps ^= 1;
            break;
        case 't':
            pPars.fUse1Hot ^= 1;
            break;
        case 'v':
            pPars.fVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    // get the input file name
    if argc == globalUtilOptind + 1 {
        pFileName = argv[globalUtilOptind];
    } else {
        Abc_Print( -1, "File name should be given on the command line.\n" );
        return 1;
    }
    Fra_FraigInductionTest( pFileName, pPars );
    return 0;

usage:
    Abc_Print( -2, "usage: testssw [-PQNFL num] [-lrfetvh] <file>\n" );
    Abc_Print( -2, "\t         performs sequential sweep using K-step induction\n" );
    Abc_Print( -2, "\t         (outputs a file with a set of pairs of equivalent nodes)\n" );
    Abc_Print( -2, "\t-P num : max partition size (0 = no partitioning) [default = %d]\n", pPars.nPartSize );
    Abc_Print( -2, "\t-Q num : partition overlap (0 = no overlap) [default = %d]\n", pPars.nOverSize );
    Abc_Print( -2, "\t-N num : number of time frames to use as the prefix [default = %d]\n", pPars.nFramesP );
    Abc_Print( -2, "\t-F num : number of time frames for induction (1=simple) [default = %d]\n", pPars.nFramesK );
    Abc_Print( -2, "\t-L num : max number of levels to consider (0=all) [default = %d]\n", pPars.nMaxLevs );
//    Abc_Print( -2, "\t-I num : max number of implications to consider [default = %d]\n", pPars->nMaxImps );
//    Abc_Print( -2, "\t-i     : toggle using implications [default = %s]\n", pPars->fUseImps? "yes": "no" );
    Abc_Print( -2, "\t-l     : toggle latch correspondence only [default = %s]\n", pPars.fLatchCorr? "yes": "no" );
    Abc_Print( -2, "\t-r     : toggle AIG rewriting [default = %s]\n", pPars.fRewrite? "yes": "no" );
    Abc_Print( -2, "\t-f     : toggle fraiging (combinational SAT sweeping) [default = %s]\n", pPars.fFraiging? "yes": "no" );
    Abc_Print( -2, "\t-e     : toggle writing implications as assertions [default = %s]\n", pPars.fWriteImps? "yes": "no" );
    Abc_Print( -2, "\t-t     : toggle using one-hotness conditions [default = %s]\n", pPars.fUse1Hot? "yes": "no" );
    Abc_Print( -2, "\t-v     : toggle verbose output [default = %s]\n", pPars.fVerbose? "yes": "no" );
    Abc_Print( -2, "\t-h     : print the command usage\n");
    return 1;
}

