/**Function*************************************************************

  Synopsis    []

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Abc_CommandCec(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    var Buffer string // was [16]byte in C

    var pNtk, pNtk1, pNtk2 *Abc_Ntk_t;
    var fDelete1, fDelete2 int32;
    var pArgvNew *string;
    var nArgcNew int32;
    var c int32;
    var fSat int32;
    var fVerbose int32;
    var nSeconds int32;
    var nPartSize int32;
    var nConfLimit int32;
    var nInsLimit int32;
    var fPartition int32;
    var fIgnoreNames int32;

    extern void Abc_NtkCecSat( Abc_Ntk_t * pNtk1, Abc_Ntk_t * pNtk2, int nConfLimit, int nInsLimit );
    extern void Abc_NtkCecFraig( Abc_Ntk_t * pNtk1, Abc_Ntk_t * pNtk2, int nSeconds, int fVerbose );
    extern void Abc_NtkCecFraigPart( Abc_Ntk_t * pNtk1, Abc_Ntk_t * pNtk2, int nSeconds, int nPartSize, int fVerbose );
    extern void Abc_NtkCecFraigPartAuto( Abc_Ntk_t * pNtk1, Abc_Ntk_t * pNtk2, int nSeconds, int fVerbose );

    pNtk = Abc_FrameReadNtk(pAbc);
    // set defaults
    fSat     =  0;
    fVerbose =  0;
    nSeconds = 20;
    nPartSize  = 0;
    nConfLimit = 10000;
    nInsLimit  = 0;
    fPartition = 0;
    fIgnoreNames = 0;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "TCIPpsnvh" ) ) != -1  {
        switch  c  {
        case 'T':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-T\" should be followed by an integer.\n" );
                goto usage;
            }
            nSeconds = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nSeconds < 0 {
                goto usage; }
            break;
        case 'C':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-C\" should be followed by an integer.\n" );
                goto usage;
            }
            nConfLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nConfLimit < 0 {
                goto usage; }
            break;
        case 'I':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-I\" should be followed by an integer.\n" );
                goto usage;
            }
            nInsLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nInsLimit < 0 {
                goto usage; }
            break;
        case 'P':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-P\" should be followed by an integer.\n" );
                goto usage;
            }
            nPartSize = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nPartSize < 0 {
                goto usage; }
            break;
        case 'p':
            fPartition ^= 1;
            break;
        case 's':
            fSat ^= 1;
            break;
        case 'n':
            fIgnoreNames ^= 1;
            break;
        case 'v':
            fVerbose ^= 1;
            break;
        default:
            goto usage;
        }
    }

    if (pNtk != nil) && pNtk.vPhases != nil {
        Abc_Print( -1, "Cannot compare networks with phases defined.\n" );
        return 1;
    }

    pArgvNew = argv + globalUtilOptind;
    nArgcNew = argc - globalUtilOptind;
    if !Abc_NtkPrepareTwoNtks( os.Stdout, pNtk, pArgvNew, nArgcNew, &pNtk1, &pNtk2, &fDelete1, &fDelete2, 1 ) {
        return 1; }

    if fIgnoreNames != 0 {
        if !fDelete1 {
            pNtk1 = Abc_NtkStrash( pNtk1, 0, 1, 0 );
            fDelete1 = 1;
        }
        if !(fDelete2 != 0) {
            pNtk2 = Abc_NtkStrash( pNtk2, 0, 1, 0 );
            fDelete2 = 1;
        }
        Abc_NtkShortNames( pNtk1 );
        Abc_NtkShortNames( pNtk2 );
    }

    // perform equivalence checking
    if fPartition != 0 {
        Abc_NtkCecFraigPartAuto( pNtk1, pNtk2, nSeconds, fVerbose );
    } else if nPartSize != 0 {
        Abc_NtkCecFraigPart( pNtk1, pNtk2, nSeconds, nPartSize, fVerbose );
    } else if fSat != 0 {
        Abc_NtkCecSat( pNtk1, pNtk2, nConfLimit, nInsLimit );
    } else {
        Abc_NtkCecFraig( pNtk1, pNtk2, nSeconds, fVerbose ); }

    if fDelete1 { Abc_NtkDelete( pNtk1 ); }
    if fDelete2 != 0 { Abc_NtkDelete( pNtk2 ); }
    return 0;

usage:
    if nPartSize == 0 {
        strcpy( Buffer, "unused" );
    } else {
        Buffer = fmt.Sprintf("%d", nPartSize); }
    Abc_Print( -2, "usage: cec [-T num] [-C num] [-I num] [-P num] [-psnvh] <file1> <file2>\n" );
    Abc_Print( -2, "\t         performs combinational equivalence checking\n" );
    Abc_Print( -2, "\t-T num : approximate runtime limit in seconds [default = %d]\n", nSeconds );
    Abc_Print( -2, "\t-C num : limit on the number of conflicts [default = %d]\n",    nConfLimit );
    Abc_Print( -2, "\t-I num : limit on the number of clause inspections [default = %d]\n", nInsLimit );
    Abc_Print( -2, "\t-P num : partition size for multi-output networks [default = %s]\n", Buffer );
    Abc_Print( -2, "\t-p     : toggle automatic partitioning [default = %s]\n", fPartition? "yes": "no" );
    Abc_Print( -2, "\t-s     : toggle \"SAT only\" and \"FRAIG + SAT\" [default = %s]\n", fSat? "SAT only": "FRAIG + SAT" );
    Abc_Print( -2, "\t-n     : toggle how CIs/COs are matched (by name or by order) [default = %s]\n", fIgnoreNames? "by order": "by name" );
    Abc_Print( -2, "\t-v     : toggle verbose output [default = %s]\n", fVerbose? "yes": "no" );
    Abc_Print( -2, "\t-h     : print the command usage\n");
    Abc_Print( -2, "\tfile1  : (optional) the file with the first network\n");
    Abc_Print( -2, "\tfile2  : (optional) the file with the second network\n");
    Abc_Print( -2, "\t         if no files are given, uses the current network and its spec\n");
    Abc_Print( -2, "\t         if one file is given, uses the current network and the file\n");
    return 1;
}


/**Function*************************************************************

  Synopsis    []

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Abc_CommandDCec(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    var pNtk, pNtk1, pNtk2 *Abc_Ntk_t;
    var fDelete1, fDelete2 int32;
    var pArgvNew *string;
    var nArgcNew int32;
    var c int32;
    var fSat int32;
    var fVerbose int32;
    var nSeconds int32;
    var nConfLimit int32;
    var nInsLimit int32;
    var fPartition int32;
    var fMiter int32;

    extern int Abc_NtkDSat( Abc_Ntk_t * pNtk, ABC_INT64_T nConfLimit, ABC_INT64_T nInsLimit, int nLearnedStart, int nLearnedDelta, int nLearnedPerce, int fAlignPol, int fAndOuts, int fNewSolver, int fVerbose );
    extern int Abc_NtkDarCec( Abc_Ntk_t * pNtk1, Abc_Ntk_t * pNtk2, int nConfLimit, int fPartition, int fVerbose );

    pNtk = Abc_FrameReadNtk(pAbc);
    // set defaults
    fSat     =  0;
    fVerbose =  0;
    nSeconds = 20;
    nConfLimit = 10000;
    nInsLimit  = 0;
    fPartition = 0;
    fMiter     = 0;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "TCIpmsvh" ) ) != -1  {
        switch  c  {
        case 'T':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-T\" should be followed by an integer.\n" );
                goto usage;
            }
            nSeconds = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nSeconds < 0 {
                goto usage; }
            break;
        case 'C':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-C\" should be followed by an integer.\n" );
                goto usage;
            }
            nConfLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nConfLimit < 0 {
                goto usage; }
            break;
        case 'I':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-I\" should be followed by an integer.\n" );
                goto usage;
            }
            nInsLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nInsLimit < 0 {
                goto usage; }
            break;
        case 'p':
            fPartition ^= 1;
            break;
        case 'm':
            fMiter ^= 1;
            break;
        case 's':
            fSat ^= 1;
            break;
        case 'v':
            fVerbose ^= 1;
            break;
        default:
            goto usage;
        }
    }

    pArgvNew = argv + globalUtilOptind;
    nArgcNew = argc - globalUtilOptind;
    if fMiter != 0 {
        if pNtk == nil {
            Abc_Print( -1, "Empty network.\n" );
            return 1;
        }
        if Abc_NtkIsStrash(pNtk) {
            pNtk1 = pNtk;
            fDelete1 = 0;

        } else {
            pNtk1 = Abc_NtkStrash( pNtk, 0, 1, 0 );
            fDelete1 = 1;
        }
        pNtk2 = nil;
        fDelete2 = 0;

    } else {
        if !Abc_NtkPrepareTwoNtks( os.Stdout, pNtk, pArgvNew, nArgcNew, &pNtk1, &pNtk2, &fDelete1, &fDelete2, 1 ) {
            return 1; }
    }

    if ((pNtk1 != nil) && Abc_NtkLatchNum(pNtk1)) || ((pNtk2 != nil) && Abc_NtkLatchNum(pNtk2)) {
        if (pNtk1 != nil) && fDelete1 { Abc_NtkDelete( pNtk1 ); }
        if (pNtk2 != nil) && (fDelete2 != 0) { Abc_NtkDelete( pNtk2 ); }
        Abc_Print( -1, "Currently this command only works for networks without latches. Run \"comb\".\n" );
        return 1;
    }

    // perform equivalence checking
    if (fSat != 0) && (fMiter != 0) {
        Abc_NtkDSat( pNtk1, nConfLimit, nInsLimit, 0, 0, 0, 0, 0, 0, fVerbose );
    } else {
        Abc_NtkDarCec( pNtk1, pNtk2, nConfLimit, fPartition, fVerbose ); }

    if fDelete1 { Abc_NtkDelete( pNtk1 ); }
    if fDelete2 != 0 { Abc_NtkDelete( pNtk2 ); }
    return 0;

usage:
    Abc_Print( -2, "usage: dcec [-T num] [-C num] [-I num] [-mpsvh] <file1> <file2>\n" );
    Abc_Print( -2, "\t         performs combinational equivalence checking\n" );
    Abc_Print( -2, "\t-T num : approximate runtime limit in seconds [default = %d]\n", nSeconds );
    Abc_Print( -2, "\t-C num : limit on the number of conflicts [default = %d]\n",    nConfLimit );
    Abc_Print( -2, "\t-I num : limit on the number of clause inspections [default = %d]\n", nInsLimit );
    Abc_Print( -2, "\t-m     : toggle working on two networks or a miter [default = %s]\n", fMiter? "miter": "two networks" );
    Abc_Print( -2, "\t-p     : toggle automatic partitioning [default = %s]\n", fPartition? "yes": "no" );
    Abc_Print( -2, "\t-s     : toggle \"SAT only\" (miter) or \"FRAIG + SAT\" [default = %s]\n", fSat? "SAT only": "FRAIG + SAT" );
    Abc_Print( -2, "\t-v     : toggles verbose output [default = %s]\n", fVerbose? "yes": "no" );
    Abc_Print( -2, "\t-h     : print the command usage\n");
    Abc_Print( -2, "\tfile1  : (optional) the file with the first network\n");
    Abc_Print( -2, "\tfile2  : (optional) the file with the second network\n");
    Abc_Print( -2, "\t         if no files are given, uses the current network and its spec\n");
    Abc_Print( -2, "\t         if one file is given, uses the current network and the file\n");
    return 1;
}

/**Function*************************************************************

  Synopsis    []

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Abc_CommandDSec(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    var SecPar Fra_Sec_t;
    var pSecPar *Fra_Sec_t = &SecPar;
    var pNtk, pNtk1, pNtk2 *Abc_Ntk_t;
    var fDelete1, fDelete2 int32;
    var pArgvNew *string;
    var nArgcNew int32;
    var c int32;
    var fCheck int32 = 1;
    var fIgnoreNames int32;

    extern int Abc_NtkDarSec( Abc_Ntk_t * pNtk1, Abc_Ntk_t * pNtk2, Fra_Sec_t * p );

    pNtk = Abc_FrameReadNtk(pAbc);
    // set defaults
    Fra_SecSetDefaultParams( pSecPar );
    pSecPar.TimeLimit = 0;
    fIgnoreNames = 0;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "FTarmfncvwh" ) ) != -1  {
        switch  c  {
        case 'F':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-F\" should be followed by an integer.\n" );
                goto usage;
            }
            pSecPar.nFramesMax = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pSecPar.nFramesMax < 0 {
                goto usage; }
            break;
        case 'T':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-T\" should be followed by an integer.\n" );
                goto usage;
            }
            pSecPar.TimeLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pSecPar.TimeLimit < 0 {
                goto usage; }
            break;
        case 'a':
            pSecPar.fPhaseAbstract ^= 1;
            break;
        case 'r':
            pSecPar.fRetimeFirst ^= 1;
            break;
        case 'm':
            pSecPar.fRetimeRegs ^= 1;
            break;
        case 'f':
            pSecPar.fFraiging ^= 1;
            break;
        case 'n':
            fIgnoreNames ^= 1;
            break;
        case 'c':
            fCheck ^= 1;
            break;
        case 'v':
            pSecPar.fVerbose ^= 1;
            break;
        case 'w':
            pSecPar.fVeryVerbose ^= 1;
            break;
        default:
            goto usage;
        }
    }

    pArgvNew = argv + globalUtilOptind;
    nArgcNew = argc - globalUtilOptind;
    if !Abc_NtkPrepareTwoNtks( os.Stdout, pNtk, pArgvNew, nArgcNew, &pNtk1, &pNtk2, &fDelete1, &fDelete2, fCheck ) {
        return 1; }
    if Abc_NtkLatchNum(pNtk1) == 0 || Abc_NtkLatchNum(pNtk2) == 0 {
        if fDelete1 { Abc_NtkDelete( pNtk1 ); }
        if fDelete2 != 0 { Abc_NtkDelete( pNtk2 ); }
        Abc_Print( -1, "The network has no latches. Used combinational command \"cec\".\n" );
        return 0;
    }

    if fIgnoreNames != 0 {
        if !fDelete1 {
            pNtk1 = Abc_NtkStrash( pNtk1, 0, 1, 0 );
            fDelete1 = 1;
        }
        if !(fDelete2 != 0) {
            pNtk2 = Abc_NtkStrash( pNtk2, 0, 1, 0 );
            fDelete2 = 1;
        }
        Abc_NtkShortNames( pNtk1 );
        Abc_NtkShortNames( pNtk2 );
    }

    // perform verification
    pAbc.Status = Abc_NtkDarSec( pNtk1, pNtk2, pSecPar );

    if fDelete1 { Abc_NtkDelete( pNtk1 ); }
    if fDelete2 != 0 { Abc_NtkDelete( pNtk2 ); }
    return 0;

usage:
    Abc_Print( -2, "usage: dsec [-F num] [-T num] [-armfncvwh] <file1> <file2>\n" );
    Abc_Print( -2, "\t         performs inductive sequential equivalence checking\n" );
    Abc_Print( -2, "\t-F num : the limit on the depth of induction [default = %d]\n", pSecPar.nFramesMax );
    Abc_Print( -2, "\t-T num : the approximate runtime limit (in seconds) [default = %d]\n", pSecPar.TimeLimit );
    Abc_Print( -2, "\t-a     : toggles the use of phase abstraction [default = %s]\n", pSecPar.fPhaseAbstract? "yes": "no" );
    Abc_Print( -2, "\t-r     : toggles forward retiming at the beginning [default = %s]\n", pSecPar.fRetimeFirst? "yes": "no" );
    Abc_Print( -2, "\t-m     : toggles min-register retiming [default = %s]\n", pSecPar.fRetimeRegs? "yes": "no" );
    Abc_Print( -2, "\t-f     : toggles the internal use of fraiging [default = %s]\n", pSecPar.fFraiging? "yes": "no" );
