func Abc_CommandSat(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    var pNtk *Abc_Ntk_t  = Abc_FrameReadNtk(pAbc);
    var c int32;
    var RetValue int32;
    var fVerbose int32;
    var nConfLimit int32;
    var nInsLimit int32;
    var clk abctime;
    // set defaults
    fVerbose   = 0;
    nConfLimit = 0;
    nInsLimit  = 0;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "CIvh" ) ) != -1  {
        switch  c  {
        case 'C':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-C\" should be followed by an integer.\n" );
                goto usage;
            }
            nConfLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nConfLimit < 0 {
                goto usage; }
            break;
        case 'I':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-I\" should be followed by an integer.\n" );
                goto usage;
            }
            nInsLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nInsLimit < 0 {
                goto usage; }
            break;
        case 'v':
            fVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }

    if pNtk == nil {
        Abc_Print( -1, "Empty network.\n" );
        return 1;
    }
    if Abc_NtkLatchNum(pNtk) > 0 {
        Abc_Print( -1, "Currently can only solve the miter for combinational circuits.\n" );
        return 0;
    }

    clk = Abc_Clock();
    if Abc_NtkIsStrash(pNtk) {
        RetValue = Abc_NtkMiterSat( pNtk, (ABC_INT64_T)nConfLimit, (ABC_INT64_T)nInsLimit, fVerbose, nil, nil );

    } else {
        assert(Abc_NtkIsLogic(pNtk), "Abc_NtkIsLogic(pNtk)");
        Abc_NtkToBdd( pNtk );
        RetValue = Abc_NtkMiterSat( pNtk, (ABC_INT64_T)nConfLimit, (ABC_INT64_T)nInsLimit, fVerbose, nil, nil );
    }

    // verify that the pattern is correct
    if RetValue == 0 && Abc_NtkPoNum(pNtk) == 1 {
        //int i;
        //Abc_Obj_t * pObj;
        var pSimInfo *int32  = Abc_NtkVerifySimulatePattern( pNtk, pNtk.pModel );
        if pSimInfo[0] != 1 {
            Abc_Print( 1, "ERROR in Abc_NtkMiterSat(): Generated counter example is invalid.\n" ); }
        ABC_FREE( pSimInfo );
        /*
        // print model
        Abc_NtkForEachPi( pNtk, pObj, i )
        {
            Abc_Print( -1, "%d", (int)(pNtk->pModel[i] > 0) );
            if ( i == 70 )
                break;
        }
        Abc_Print( -1, "\n" );
        */
    }
    pAbc.Status = RetValue;
    if RetValue == -1 {
        Abc_Print( 1, "UNDECIDED      " );
    } else if RetValue == 0 {
        Abc_Print( 1, "SATISFIABLE    " );
    } else {
        Abc_Print( 1, "UNSATISFIABLE  " ); }
    //Abc_Print( -1, "\n" );
    Abc_PrintTime( 1, "Time", Abc_Clock() - clk );
    return 0;

usage:
    Abc_Print( -2, "usage: sat [-C num] [-I num] [-vh]\n" );
    Abc_Print( -2, "\t         solves the combinational miter using SAT solver MiniSat-1.14\n" );
    Abc_Print( -2, "\t         derives CNF from the current network and leave it unchanged\n" );
    Abc_Print( -2, "\t         (there is also a newer SAT solving command \"dsat\")\n" );
    Abc_Print( -2, "\t-C num : limit on the number of conflicts [default = %d]\n",    nConfLimit );
    Abc_Print( -2, "\t-I num : limit on the number of inspections [default = %d]\n", nInsLimit );
    Abc_Print( -2, "\t-v     : prints verbose information [default = %s]\n", fVerbose? "yes": "no" );
    Abc_Print( -2, "\t-h     : print the command usage\n");
    return 1;
}

/**Function*************************************************************

  Synopsis    []

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Abc_CommandDSat(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    var pNtk *Abc_Ntk_t  = Abc_FrameReadNtk(pAbc);
    var c int32;
    var RetValue int32;
    var fAlignPol int32;
    var fAndOuts int32;
    var fNewSolver int32;
    var fSilent int32;
    var fShowPattern int32;
    var fVerbose int32;
    var nConfLimit int32;
    var nLearnedStart int32;
    var nLearnedDelta int32;
    var nLearnedPerce int32;
    var nInsLimit int32;
    var clk abctime;

    extern int Abc_NtkDSat( Abc_Ntk_t * pNtk, ABC_INT64_T nConfLimit, ABC_INT64_T nInsLimit, int nLearnedStart, int nLearnedDelta, int nLearnedPerce, int fAlignPol, int fAndOuts, int fNewSolver, int fVerbose );
    // set defaults
    fAlignPol  = 0;
    fAndOuts   = 0;
    fNewSolver = 0;
    fSilent    = 0;
    fShowPattern = 0;
    fVerbose   = 0;
    nConfLimit = 0;
    nInsLimit  = 0;
    nLearnedStart = 0;
    nLearnedDelta = 0;
    nLearnedPerce = 0;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "CILDEpansvwh" ) ) != -1  {
        switch  c  {
        case 'C':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-C\" should be followed by an integer.\n" );
                goto usage;
            }
            nConfLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nConfLimit < 0 {
                goto usage; }
            break;
        case 'I':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-I\" should be followed by an integer.\n" );
                goto usage;
            }
            nInsLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nInsLimit < 0 {
                goto usage; }
            break;
        case 'L':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-L\" should be followed by an integer.\n" );
                goto usage;
            }
            nLearnedStart = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nLearnedStart < 0 {
                goto usage; }
            break;
        case 'D':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-D\" should be followed by an integer.\n" );
                goto usage;
            }
            nLearnedDelta = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nLearnedDelta < 0 {
                goto usage; }
            break;
        case 'E':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-E\" should be followed by an integer.\n" );
                goto usage;
            }
            nLearnedPerce = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nLearnedPerce < 0 {
                goto usage; }
            break;
        case 'p':
            fAlignPol ^= 1;
            break;
        case 'a':
            fAndOuts ^= 1;
            break;
        case 'n':
            fNewSolver ^= 1;
            break;
        case 's':
            fSilent ^= 1;
            break;
        case 'v':
            fVerbose ^= 1;
            break;
        case 'w':
            fShowPattern ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }

    if argc == globalUtilOptind + 1 {
        var pModel *int32  = nil;
        extern int Cnf_DataSolveFromFile( char * pFileName, int nConfLimit, int nLearnedStart, int nLearnedDelta, int nLearnedPerce, int fVerbose, int fShowPattern, int ** ppModel, int nPis );
        // get the input file name
        var pFileName string  = argv[globalUtilOptind];
        var pFile *os.File  = os.Open(pFileName);
        if pFile == nil {
            fmt.Printf("Cannot open file \"%s\" for writing.\n", pFileName);
            return 0;
        }
        _ = (pFile).Close();
        Cnf_DataSolveFromFile( pFileName, nConfLimit, nLearnedStart, nLearnedDelta, nLearnedPerce, fVerbose, fShowPattern, &pModel, pNtk ? Abc_NtkPiNum(pNtk) : 0 );
        if (pModel != nil) && (pNtk != nil) {
            var pSimInfo *int32  = Abc_NtkVerifySimulatePattern( pNtk, pModel );
            if pSimInfo[0] != 1 {
                Abc_Print( 1, "ERROR in mapping PIs into SAT vars: Generated CEX is invalid.\n" ); }
            ABC_FREE( pSimInfo );
            pAbc.pCex = Abc_CexCreate( 0, Abc_NtkPiNum(pNtk), pModel, 0, 0, 0 );
        }
        ABC_FREE( pModel );
        return 0;
    }
    if pNtk == nil {
        Abc_Print( -1, "Empty network.\n" );
        return 1;
    }
    if Abc_NtkLatchNum(pNtk) > 0 {
        Abc_Print( -1, "Currently can only solve the miter for combinational circuits.\n" );
        return 0;
    }

    if Abc_NtkPoNum(pNtk) != 1 {
        Abc_Print( -1, "Currently expects a single-output miter.\n" );
        return 0;
    }

    if !Abc_NtkIsStrash(pNtk) {
        Abc_Print( -1, "Currently only works for structurally hashed circuits.\n" );
        return 0;
    }
    clk = Abc_Clock();
    RetValue = Abc_NtkDSat( pNtk, (ABC_INT64_T)nConfLimit, (ABC_INT64_T)nInsLimit, nLearnedStart, nLearnedDelta, nLearnedPerce, fAlignPol, fAndOuts, fNewSolver, fVerbose );
    // verify that the pattern is correct
    if RetValue == 0 && Abc_NtkPoNum(pNtk) == 1 {
        var pSimInfo *int32  = Abc_NtkVerifySimulatePattern( pNtk, pNtk.pModel );
        if pSimInfo[0] != 1 {
            Abc_Print( 1, "ERROR in Abc_NtkMiterSat(): Generated counter example is invalid.\n" ); }
        ABC_FREE( pSimInfo );
        pAbc.pCex = Abc_CexCreate( 0, Abc_NtkPiNum(pNtk), pNtk.pModel, 0, 0, 0 );
    }
    pAbc.Status = RetValue;
    if !(fSilent != 0) {
        if RetValue == -1 {
            Abc_Print( 1, "UNDECIDED      " );
        } else if RetValue == 0 {
            Abc_Print( 1, "SATISFIABLE    " );
        } else {
            Abc_Print( 1, "UNSATISFIABLE  " ); }
        Abc_PrintTime( 1, "Time", Abc_Clock() - clk );
    }
    return 0;

usage:
    Abc_Print( -2, "usage: dsat [-CILDE num] [-pansvh]\n" );
    Abc_Print( -2, "\t         solves the combinational miter using SAT solver MiniSat-1.14\n" );
    Abc_Print( -2, "\t         derives CNF from the current network and leaves it unchanged\n" );
    Abc_Print( -2, "\t-C num : limit on the number of conflicts [default = %d]\n",    nConfLimit );
    Abc_Print( -2, "\t-I num : limit on the number of inspections [default = %d]\n", nInsLimit );
    Abc_Print( -2, "\t-L num : starting value for learned clause removal [default = %d]\n", nLearnedStart );
    Abc_Print( -2, "\t-D num : delta value for learned clause removal [default = %d]\n", nLearnedDelta );
    Abc_Print( -2, "\t-E num : ratio percentage for learned clause removal [default = %d]\n", nLearnedPerce );
    Abc_Print( -2, "\t-p     : align polarity of SAT variables [default = %s]\n", fAlignPol? "yes": "no" );
    Abc_Print( -2, "\t-a     : toggle ANDing/ORing of miter outputs [default = %s]\n", fAndOuts? "ANDing": "ORing" );
    Abc_Print( -2, "\t-n     : toggle using new solver [default = %s]\n", fNewSolver? "yes": "no" );
    Abc_Print( -2, "\t-s     : enable silent computation (no reporting) [default = %s]\n", fSilent? "yes": "no" );
    Abc_Print( -2, "\t-v     : prints verbose information [default = %s]\n", fVerbose? "yes": "no" );
    Abc_Print( -2, "\t-h     : print the command usage\n");
    return 1;
}

