/**Function*************************************************************

  Synopsis    []

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Abc_CommandBmc(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    var pNtk *Abc_Ntk_t  = Abc_FrameReadNtk(pAbc);
    var c int32;
    var nFrames int32;
    var nSizeMax int32;
    var nBTLimit int32;
    var nBTLimitAll int32;
    var nNodeDelta int32;
    var fRewrite int32;
    var fNewAlgo int32;
    var nCofFanLit int32;
    var fVerbose int32;
    var iFrames int32;
    var fUseSatoko int32;
    var pLogFileName string  = nil;

    extern int Abc_NtkDarBmc( Abc_Ntk_t * pNtk, int nStart, int nFrames, int nSizeMax, int nNodeDelta, int nTimeOut, int nBTLimit, int nBTLimitAll, int fRewrite, int fNewAlgo, int fOrDecomp, int nCofFanLit, int fVerbose, int * piFrames, int fUseSatoko );
    // set defaults
    nFrames     =       20;
    nSizeMax    =   100000;
    nBTLimit    =        0;
    nBTLimitAll =        0;
    nNodeDelta  =     1000;
    fRewrite    =        0;
    fNewAlgo    =        1;
    nCofFanLit  =        0;
    fVerbose    =        0;
    fUseSatoko  =        0;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "FNCGDLrsvh" ) ) != -1  {
        switch  c  {
        case 'F':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-F\" should be followed by an integer.\n" );
                goto usage;
            }
            nFrames = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nFrames < 0 {
                goto usage; }
            break;
        case 'N':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-N\" should be followed by an integer.\n" );
                goto usage;
            }
            nSizeMax = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nSizeMax < 0 {
                goto usage; }
            break;
        case 'C':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-C\" should be followed by an integer.\n" );
                goto usage;
            }
            nBTLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nBTLimit < 0 {
                goto usage; }
            break;
        case 'G':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-G\" should be followed by an integer.\n" );
                goto usage;
            }
            nBTLimitAll = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nBTLimitAll < 0 {
                goto usage; }
            break;
        case 'D':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-D\" should be followed by an integer.\n" );
                goto usage;
            }
            nNodeDelta = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nNodeDelta < 0 {
                goto usage; }
            break;
/*
        case 'L':
            if ( globalUtilOptind >= argc )
            {
                Abc_Print( -1, "Command line switch \"-L\" should be followed by an integer.\n" );
                goto usage;
            }
            nCofFanLit = atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if ( nCofFanLit < 0 )
                goto usage;
            break;
*/
        case 'L':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-L\" should be followed by a file name.\n" );
                goto usage;
            }
            pLogFileName = argv[globalUtilOptind];
            globalUtilOptind++;
            break;
        case 'r':
            fRewrite ^= 1;
            break;
        case 'a':
            fNewAlgo ^= 1;
            break;
        case 's':
            fUseSatoko ^= 1;
            break;
        case 'v':
            fVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    if pNtk == nil {
        Abc_Print( -1, "Empty network.\n" );
        return 1;
    }
    if !Abc_NtkIsStrash(pNtk) {
        Abc_Print( -1, "Currently only works for structurally hashed circuits.\n" );
        return 0;
    }
    if Abc_NtkLatchNum(pNtk) == 0 {
        Abc_Print( -1, "Does not work for combinational networks.\n" );
        return 0;
    }
    if pAbc.fBatchMode && (pAbc.Status == 0 || pAbc.Status == 1) { 
        Abc_Print( 1, "The miters is already solved; skipping the command.\n" ); 
        return 0;
    }
    pAbc.Status = Abc_NtkDarBmc( pNtk, 0, nFrames, nSizeMax, nNodeDelta, 0, nBTLimit, nBTLimitAll, fRewrite, fNewAlgo, 0, nCofFanLit, fVerbose, &iFrames, fUseSatoko );
    pAbc.nFrames = iFrames;
    Abc_FrameReplaceCex( pAbc, &pNtk.pSeqModel );
    if pLogFileName {
        Abc_NtkWriteLogFile( pLogFileName, pAbc.pCex, pAbc.Status, pAbc.nFrames, "bmc" ); }
    return 0;

usage:
    Abc_Print( -2, "usage: bmc [-FNC num] [-L file] [-rcsvh]\n" );
    Abc_Print( -2, "\t         performs bounded model checking with static unrolling\n" );
    Abc_Print( -2, "\t-F num : the number of time frames [default = %d]\n", nFrames );
    Abc_Print( -2, "\t-N num : the max number of nodes in the frames [default = %d]\n", nSizeMax );
