    fVerbose    =        0;
    fUseSatoko  =        0;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "SFNTCGDLrusvh" ) ) != -1  {
        switch  c  {
        case 'S':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-S\" should be followed by an integer.\n" );
                goto usage;
            }
            nStart = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nStart < 0 {
                goto usage; }
            break;
        case 'F':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-F\" should be followed by an integer.\n" );
                goto usage;
            }
            nFrames = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nFrames < 0 {
                goto usage; }
            break;
        case 'N':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-N\" should be followed by an integer.\n" );
                goto usage;
            }
            nSizeMax = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nSizeMax < 0 {
                goto usage; }
            break;
        case 'T':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-T\" should be followed by an integer.\n" );
                goto usage;
            }
            nTimeOut = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nTimeOut < 0 {
                goto usage; }
            break;
        case 'C':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-C\" should be followed by an integer.\n" );
                goto usage;
            }
            nBTLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nBTLimit < 0 {
                goto usage; }
            break;
        case 'G':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-G\" should be followed by an integer.\n" );
                goto usage;
            }
            nBTLimitAll = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nBTLimitAll < 0 {
                goto usage; }
            break;
        case 'D':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-D\" should be followed by an integer.\n" );
                goto usage;
            }
            nNodeDelta = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nNodeDelta < 0 {
                goto usage; }
            break;
        case 'L':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-L\" should be followed by a file name.\n" );
                goto usage;
            }
            pLogFileName = argv[globalUtilOptind];
            globalUtilOptind++;
            break;
        case 'r':
            fRewrite ^= 1;
            break;
        case 'a':
            fNewAlgo ^= 1;
            break;
        case 'u':
            fOrDecomp ^= 1;
            break;
        case 's':
            fUseSatoko ^= 1;
            break;
        case 'v':
            fVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    if pNtk == nil {
        Abc_Print( -1, "Empty network.\n" );
        return 1;
    }
    if !Abc_NtkIsStrash(pNtk) {
