    }
    if Abc_NtkLatchNum(pNtk) == 0 {
        Abc_Print( -1, "Does not work for combinational networks.\n" );
        return 0;
    }
    if pAbc.fBatchMode && (pAbc.Status == 0 || pAbc.Status == 1) { 
        Abc_Print( 1, "The miters is already solved; skipping the command.\n" ); 
