    Saig_ParBmcSetDefaultParams( pPars );
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "SFTHGCDJIPQRLWaxdursgvzh" ) ) != -1  {
        switch  c  {
