                goto usage;
            }
            pPars.nTimeOutGap = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nTimeOutGap < 0 {
                goto usage; }
            break;
        case 'C':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-C\" should be followed by an integer.\n" );
