        case 'D':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-D\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nConfLimitJump = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nConfLimitJump < 0 {
                goto usage; }
