                Abc_Print( -1, "Command line switch \"-J\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nFramesJump = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nFramesJump < 0 {
                goto usage; }
            break;
        case 'I':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-I\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nPisAbstract = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nPisAbstract < 0 {
                goto usage; }
            break;
        case 'P':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-P\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nLearnedStart = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nLearnedStart < 0 {
                goto usage; }
