        case 'Q':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-Q\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nLearnedDelta = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nLearnedDelta < 0 {
                goto usage; }
