        case 'R':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-R\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nLearnedPerce = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nLearnedPerce < 0 {
