/**Function*************************************************************

  Synopsis    [Compares to versions of the design and finds the best.]

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Abc_NtkCompareWithBest(pBest *Abc_Ntk_t, p *Abc_Ntk_t, pnBestNtkArea *float32, pnBestNtkDelay *float32, pnBestNtkNodes *int32, pnBestNtkLevels *int32, fArea int32) int32 { 
    var nNtkArea float32    = float32(Abc_NtkGetMappedArea(p));
    var nNtkDelay float32   = float32(Abc_NtkDelayTrace(p, nil, nil, 0));
    var nNtkNodes int32   = Abc_NtkNodeNum(p);
    var nNtkLevels int32  = Abc_NtkLevel(p);

    if pBest == nil ||
         Abc_NtkPiNum(pBest)    != Abc_NtkPiNum(p)    ||
         Abc_NtkPoNum(pBest)    != Abc_NtkPoNum(p)    ||
         Abc_NtkLatchNum(pBest) != Abc_NtkLatchNum(p) ||
         (int32(strings.Compare(Abc_NtkName(pBest), Abc_NtkName(p))) != 0)   ||
         (!(fArea != 0) && (*pnBestNtkLevels > nNtkLevels || (*pnBestNtkLevels == nNtkLevels && *pnBestNtkDelay > nNtkDelay ))) ||
         ( (fArea != 0) && (*pnBestNtkNodes  > nNtkNodes  || (*pnBestNtkNodes  == nNtkNodes  && *pnBestNtkArea  > nNtkArea  ))) {
        *pnBestNtkArea   = nNtkArea;
        *pnBestNtkDelay  = nNtkDelay; 
        *pnBestNtkNodes  = nNtkNodes;
        *pnBestNtkLevels = nNtkLevels;
        fmt.Printf("\nUpdating the best network (Area = %10.2f  Delay = %10.2f  Nodes = %6d  Level = %6d).\n\n", nNtkArea, nNtkDelay, nNtkNodes, nNtkLevels);
        return 1;
    }
    return 0;
}

/**Function*************************************************************

  Synopsis    []

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Abc_CommandAbcSave(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    var c, fArea int32;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "ah" ) ) != -1  {
        switch  c  {
        case 'a':
            fArea ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    if pAbc.pNtkCur == nil {
        Abc_Print( -1, "Empty network.\n" );
        return 1;
    }
    if !Abc_NtkHasMapping(pAbc.pNtkCur) {
        Abc_Print( -1, "Network has no mapping.\n" );
        return 1;
    }
    if !(Abc_NtkCompareWithBest( pAbc.pNtkBest, pAbc.pNtkCur, 
             &pAbc.nBestNtkArea,  &pAbc.nBestNtkDelay, 
             &pAbc.nBestNtkNodes, &pAbc.nBestNtkLevels, fArea ) != 0) {
        return 0; }
    // save the design as best
    if pAbc.pNtkBest { Abc_NtkDelete( pAbc.pNtkBest ); }
    pAbc.pNtkBest = Abc_NtkDup(pAbc.pNtkCur);
    return 0;

usage:
    Abc_Print( -2, "usage: save [-ah]\n" );
    Abc_Print( -2, "\t        compares and possibly saves network with mapping\n" );
    Abc_Print( -2, "\t-a    : toggle using area as the primary metric [default = %s]\n", fArea? "yes": "no" );
    Abc_Print( -2, "\t-h    : print the command usage\n");
    return 1;
}

