/**Function*************************************************************

  Synopsis    []

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Abc_CommandAbc9Read(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    extern void Abc3_ReadShowHie( char * pFileName, int fFlat );
    extern Gia_Man_t * Gia_MiniAigSuperDerive( char * pFileName, int fVerbose );
    var pAig *Gia_Man_t  = nil;
    var pFile *os.File;
    var pArgvNew *string;
    var FileName, pTemp string;
    var c, nArgcNew int32;
    var fMiniAig int32;
    var fMiniAig2 int32;
    var fMiniLut int32;
    var fVerbose int32;
    var fGiaSimple int32;
    var fSkipStrash int32;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "csmnlvh" ) ) != -1  {
        switch  c  {
        case 'c':
            fGiaSimple ^= 1;
            break;
        case 's':
            fSkipStrash ^= 1;
            break;
        case 'm':
            fMiniAig ^= 1;
            break;
        case 'n':
            fMiniAig2 ^= 1;
            break;
        case 'l':
            fMiniLut ^= 1;
            break;
        case 'v':
            fVerbose ^= 1;
            break;
        default:
            goto usage;
        }
    }
    pArgvNew = argv + globalUtilOptind;
    nArgcNew = argc - globalUtilOptind;
    if nArgcNew != 1 {
        Abc_Print( -1, "There is no file name.\n" );
        return 1;
    }

    // get the input file name
    FileName = pArgvNew[0];
    // fix the wrong symbol
    for  pTemp = FileName; *pTemp; pTemp++  {
        if *pTemp == '>' {
            *pTemp = '\\'; }
    }
    if (pFile = os.Open(FileName)) == nil {
        Abc_Print( -1, "Cannot open input file \"%s\". ", FileName );
        if FileName = Extra_FileGetSimilarName( FileName, ".aig", ".blif", ".pla", ".eqn", ".bench" ) {
            Abc_Print( 1, "Did you mean \"%s\"?", FileName ); }
        Abc_Print( 1, "\n" );
        return 1;
    }
    _ = (pFile).Close();

    if fMiniAig != 0 {
        pAig = Gia_ManReadMiniAig( FileName );
    } else if fMiniAig2 != 0 {
        pAig = Gia_MiniAigSuperDerive( FileName, fVerbose );
    } else if fMiniLut != 0 {
        pAig = Gia_ManReadMiniLut( FileName );
//    else if ( Extra_FileIsType( FileName, ".v", NULL, NULL ) )
//        Abc3_ReadShowHie( FileName, fSkipStrash );
    } else {
        pAig = Gia_AigerRead( FileName, fGiaSimple, fSkipStrash, 0 ); }
    if pAig {
        Abc_FrameUpdateGia( pAbc, pAig ); }
    return 0;

usage:
    Abc_Print( -2, "usage: &r [-csmnlvh] <file>\n" );
    Abc_Print( -2, "\t         reads the current AIG from the AIGER file\n" );
    Abc_Print( -2, "\t-c     : toggles reading simple AIG [default = %s]\n", fGiaSimple? "yes": "no" );
    Abc_Print( -2, "\t-s     : toggles structural hashing while reading [default = %s]\n", !fSkipStrash? "yes": "no" );
    Abc_Print( -2, "\t-m     : toggles reading MiniAIG rather than AIGER file [default = %s]\n", fMiniAig? "yes": "no" );
    Abc_Print( -2, "\t-n     : toggles reading MiniAIG as a set of supergates [default = %s]\n", fMiniAig2? "yes": "no" );
    Abc_Print( -2, "\t-l     : toggles reading MiniLUT rather than AIGER file [default = %s]\n", fMiniLut? "yes": "no" );
    Abc_Print( -2, "\t-v     : toggles additional verbose output [default = %s]\n", fVerbose? "yes": "no" );
    Abc_Print( -2, "\t-h     : print the command usage\n");
    Abc_Print( -2, "\t<file> : the file name\n");
    return 1;
}

