/**Function*************************************************************

  Synopsis    []

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Abc_CommandAbc9PrintTruth(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    extern word Gia_LutComputeTruth6Simple( Gia_Man_t * p, int iPo );
    var i int32;
    var c int32;
    var iOutNum int32;
    var nOutRange int32 = -1;
    var fVerbose int32; var Truth word;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "ORvh" ) ) != -1  {
        switch  c  {
        case 'O':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-O\" should be followed by an integer.\n" );
                goto usage;
            }
            iOutNum = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if iOutNum < 0 {
                goto usage; }
            break;
        case 'R':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-R\" should be followed by an integer.\n" );
                goto usage;
            }
            nOutRange = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nOutRange < 0 {
                goto usage; }
            break;
        case 'v':
            fVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    if pAbc.pGia == nil {
        Abc_Print( -1, "Abc_CommandAbc9PrintTruth(): There is no AIG.\n" );
        return 1;
    }
    if Gia_ManPiNum(pAbc.pGia) > 6 {
        Abc_Print( -1, "The number of inputs of the AIG exceeds 6.\n" );
        return 1;
    }
    if iOutNum < 0 || iOutNum + nOutRange > Gia_ManPoNum(pAbc.pGia) {
        Abc_Print( -1, "Abc_CommandAbc9PrintTruth(): Range of outputs to extract is incorrect.\n" );
        return 1;
    }
    if nOutRange == -1 {
        nOutRange = Gia_ManCoNum(pAbc.pGia); }
    for  i = iOutNum; i < iOutNum + nOutRange; i++  {
        Truth = Gia_LutComputeTruth6Simple( pAbc.pGia, i );
        fmt.Printf("Output %8d : ", i);
        Extra_PrintHex( os.Stdout, (unsigned *)&Truth, Gia_ManCiNum(pAbc.pGia) );
        fmt.Printf("\n");
    }
    return 0;

usage:
    Abc_Print( -2, "usage: &print_truth [-OR num] [-vh]\n" );
    Abc_Print( -2, "\t         prints truth tables of outputs in hex notation\n" );
    Abc_Print( -2, "\t-O num : the index of first PO to print [default = %d]\n", iOutNum );
