                goto usage; }
            break;
        case 'l':
            fKeepLevel ^= 1;
            break;
        case 'v':
            fVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    if pAbc.pGia == nil {
        Abc_Print( -1, "Abc_CommandAbc9Shrink(): There is no AIG.\n" );
