            }
            pPars.nBTLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nBTLimit < 0 {
                goto usage; }
            break;
        case 'T':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-T\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.TimeLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.TimeLimit < 0 {
                goto usage; }
            break;
        case 'n':
            pPars.fNaive ^= 1;
            break;
        case 'm':
            fMiter ^= 1;
            break;
        case 'd':
            fDualOutput ^= 1;
            break;
        case 'a':
            fDumpMiter ^= 1;
            break;
        case 's':
            pPars.fSilent ^= 1;
            break;
        case 'x':
            fUseNew ^= 1;
            break;
        case 'v':
            pPars.fVerbose ^= 1;
            break;
        case 'w':
            pPars.fVeryVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    pArgvNew = argv + globalUtilOptind;
    nArgcNew = argc - globalUtilOptind;
    if fMiter != 0 {
        if pAbc.pGia == nil || nArgcNew != 0 {
            Abc_Print( -1, "Abc_CommandAbc9Cec(): A miter cannot be given as an argument of command &cec and should be entered using &r.\n" );
            return 1;
        }
        if fDualOutput {
            if Gia_ManPoNum(pAbc.pGia) & 1 {
                Abc_Print( -1, "The dual-output miter should have an even number of outputs.\n" );
                return 1;
            }
            if !pPars.fSilent {
            Abc_Print( 1, "Assuming the current network is a double-output miter.\n" ); }
            pAbc.Status = Cec_ManVerify( pAbc.pGia, pPars );

        } else {
            var clk abctime  = Abc_Clock();
            var pObj *Gia_Obj_t; var i int32;
            if !pPars.fSilent {
            Abc_Print( 1, "Assuming the current network is a single-output miter.\n" ); }
            // handle the case when the output is disproved by an all-0 primary input pattern
            ABC_FREE( pAbc.pGia.pCexComb );
            Gia_ManSetPhase( pAbc.pGia );
            Gia_ManForEachCo( pAbc.pGia, pObj, i )
                if pObj.fPhase {
                    pAbc.pGia.pCexComb = Abc_CexAlloc( 0, Gia_ManCiNum(pAbc.pGia), 1 );
                    if !pPars.fSilent {
                        Abc_Print( 1, "Networks are NOT EQUIVALENT. Output %d trivially differs (different phase).  ", i );
                        Abc_PrintTime( 1, "Time", Abc_Clock() - clk );
                    }
                    pAbc.Status = 0;// satisfiable
                    break;
                }
            if pAbc.pGia.pCexComb == nil {
                var pTemp *Gia_Man_t  = Gia_ManDemiterToDual( pAbc.pGia );
                pAbc.Status = Cec_ManVerify( pTemp, pPars );
                ABC_SWAP( Abc_Cex_t *, pAbc.pGia.pCexComb, pTemp.pCexComb );
                Gia_ManStop( pTemp );
            }
        }
        Abc_FrameReplaceCex( pAbc, &pAbc.pGia.pCexComb );
        return 0;
    }
    if nArgcNew > 2 {
        Abc_Print( -1, "Abc_CommandAbc9Cec(): Wrong number of command-line arguments.\n" );
        return 1;
    }
    if nArgcNew == 2 {
        var pFileNames [2]string = [2]string{ pArgvNew[0], pArgvNew[1] };
        var pTemp string;
        var n int32;
        for  n = 0; n < 2; n++  {
            // fix the wrong symbol
            for  pTemp = pFileNames[n]; *pTemp; pTemp++  {
                if *pTemp == '>' {
                    *pTemp = '\\'; }
            }
            if (pFile = os.Open(pFileNames[n])) == nil {
                Abc_Print( -1, "Cannot open input file \"%s\". ", pFileNames[n] );
                if pFileNames[n] = Extra_FileGetSimilarName( pFileNames[n], ".aig", nil, nil, nil, nil ) {
                    Abc_Print( 1, "Did you mean \"%s\"?", pFileNames[n] ); }
                Abc_Print( 1, "\n" );
                return 1;
            }
            _ = (pFile).Close();
            pGias[n] = Gia_AigerRead( pFileNames[n], 0, 0, 0 );
            if pGias[n] == nil {
                Abc_Print( -1, "Reading AIGER from file \"%s\" has failed.\n", pFileNames[n] );
                return 0;
            }
        }

    } else {
        var FileName, pTemp string;
        if pAbc.pGia == nil {
            Abc_Print( -1, "Abc_CommandAbc9Cec(): There is no current AIG.\n" );
            return 1;
        }
        pGias[0] = pAbc.pGia;
        if nArgcNew == 1 {
            FileName = pArgvNew[0];
        } else {
            assert(nArgcNew == 0, "nArgcNew == 0");
            if pAbc.pGia.pSpec == nil {
                Abc_Print( -1, "File name is not given on the command line.\n" );
                return 1;
            }
            FileName = pAbc.pGia.pSpec;
        }
        // fix the wrong symbol
        for  pTemp = FileName; *pTemp; pTemp++  {
            if *pTemp == '>' {
                *pTemp = '\\'; }
        }
        if (pFile = os.Open(FileName)) == nil {
            Abc_Print( -1, "Cannot open input file \"%s\". ", FileName );
            if FileName = Extra_FileGetSimilarName( FileName, ".aig", nil, nil, nil, nil ) {
                Abc_Print( 1, "Did you mean \"%s\"?", FileName ); }
            Abc_Print( 1, "\n" );
            return 1;
        }
        _ = (pFile).Close();
        pGias[1] = Gia_AigerRead( FileName, 0, 0, 0 );
        if pGias[1] == nil {
            Abc_Print( -1, "Reading AIGER has failed.\n" );
            return 0;
        }
    }
    // compute the miter
    pMiter = Gia_ManMiter( pGias[0], pGias[1], 0, !fUseNew, 0, 0, pPars.fVerbose );
    if pMiter != nil {
        if fDumpMiter != 0 {
            Abc_Print( 0, "The verification miter is written into file \"%s\".\n", "cec_miter.aig" );
            Gia_AigerWrite( pMiter, "cec_miter.aig", 0, 0, 0 );
        }
        if pGias[0].vSimsPi {
            pMiter.vSimsPi = Vec_WrdDup(pGias[0].vSimsPi); 
            pMiter.nSimWords = pGias[0].nSimWords;
        }
        if fUseNew {
            var clk abctime  = Abc_Clock();
            extern Gia_Man_t * Cec4_ManSimulateTest3( Gia_Man_t * p, int nBTLimit, int fVerbose );
            var pNew *Gia_Man_t  = Cec4_ManSimulateTest3( pMiter, pPars.nBTLimit, pPars.fVerbose );
            if Gia_ManAndNum(pNew) == 0 {
                Abc_Print( 1, "Networks are equivalent.  " );
            } else {
                Abc_Print( 1, "Networks are NOT EQUIVALENT.  " ); }
            Abc_PrintTime( 1, "Time", Abc_Clock() - clk );
            Gia_ManStop( pNew );

        } else {
            pAbc.Status = Cec_ManVerify( pMiter, pPars );
            Abc_FrameReplaceCex( pAbc, &pGias[0].pCexComb );
        }
        Gia_ManStop( pMiter );
    }
    if pGias[0] != pAbc.pGia {
        Gia_ManStop( pGias[0] ); }
    Gia_ManStop( pGias[1] );
    return 0;

usage:
    Abc_Print( -2, "usage: &cec [-CT num] [-nmdasxvwh]\n" );
    Abc_Print( -2, "\t         new combinational equivalence checker\n" );
    Abc_Print( -2, "\t-C num : the max number of conflicts at a node [default = %d]\n", pPars.nBTLimit );
    Abc_Print( -2, "\t-T num : approximate runtime limit in seconds [default = %d]\n", pPars.TimeLimit );
    Abc_Print( -2, "\t-n     : toggle using naive SAT-based checking [default = %s]\n", pPars.fNaive? "yes":"no");
    Abc_Print( -2, "\t-m     : toggle miter vs. two circuits [default = %s]\n", fMiter? "miter":"two circuits");
    Abc_Print( -2, "\t-d     : toggle using dual output miter [default = %s]\n", fDualOutput? "yes":"no");
    Abc_Print( -2, "\t-a     : toggle writing dual-output miter [default = %s]\n", fDumpMiter? "yes":"no");
    Abc_Print( -2, "\t-s     : toggle silent operation [default = %s]\n", pPars.fSilent ? "yes":"no");
    Abc_Print( -2, "\t-x     : toggle using new solver [default = %s]\n", fUseNew? "yes":"no");
    Abc_Print( -2, "\t-v     : toggle verbose output [default = %s]\n", pPars.fVerbose? "yes":"no");
    Abc_Print( -2, "\t-w     : toggle printing SAT solver statistics [default = %s]\n", pPars.fVeryVerbose? "yes":"no");
    Abc_Print( -2, "\t-h     : print the command usage\n");
    return 1;
}

