/**Function*************************************************************

  Synopsis    []

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Abc_CommandAbc9Dsdb(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    var pTemp *Gia_Man_t;
    var nLevelMax int32;
    var nTimeWindow int32;
    var nLutSize int32     = 6;
    var nCutNum int32      = 8;
    var nRelaxRatio int32;
    var c, fVerbose int32;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "LWKCRvh" ) ) != -1  {
        switch  c  {
        case 'L':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-L\" should be followed by an integer.\n" );
                goto usage;
            }
            nLevelMax = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nLevelMax < 0 {
                goto usage; }
            break;
        case 'W':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-W\" should be followed by an integer.\n" );
                goto usage;
            }
            nTimeWindow = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nTimeWindow < 0 {
                goto usage; }
            break;
        case 'K':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-K\" should be followed by an integer.\n" );
                goto usage;
            }
            nLutSize = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nLutSize < 0 {
                goto usage; }
            break;
         case 'C':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-C\" should be followed by an integer.\n" );
                goto usage;
            }
            nCutNum = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nCutNum < 0 {
                goto usage; }
            break;
        case 'R':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-R\" should be followed by an integer.\n" );
                goto usage;
            }
            nRelaxRatio = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nRelaxRatio < 0 {
                goto usage; }
            break;
        case 'v':
            fVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    if pAbc.pGia == nil {
        Abc_Print( -1, "Abc_CommandAbc9Dsdb(): There is no AIG.\n" );
        return 1;
    }
    if nLutSize > DAU_MAX_VAR {
        fmt.Printf("Abc_CommandAbc9Dsdb(): Size of the required DSD manager (%d) exceeds the precompiled limit (%d) (change parameter DAU_MAX_VAR).\n", nLutSize, DAU_MAX_VAR);
        return 0;
    }
    if Abc_FrameReadManDsd2() && nLutSize > If_DsdManVarNum((If_DsdMan_t*)Abc_FrameReadManDsd2()) {
        fmt.Printf("Abc_CommandAbc9Dsdb(): Incompatible size of the DSD manager (run \"dsd_free -b\").\n");
        return 0;
    }
    if (nLevelMax != 0) || (nTimeWindow != 0) {
        pTemp = Gia_ManPerformDsdBalanceWin( pAbc.pGia, nLevelMax, nTimeWindow, nLutSize, nCutNum, nRelaxRatio, fVerbose );
    } else {
        pTemp = Gia_ManPerformDsdBalance( pAbc.pGia, nLutSize, nCutNum, nRelaxRatio, fVerbose ); }
    Abc_FrameUpdateGia( pAbc, pTemp );
    return 0;

usage:
    Abc_Print( -2, "usage: &dsdb [-LWKCR num] [-vh]\n" );
    Abc_Print( -2, "\t         performs DSD balancing\n" );
    Abc_Print( -2, "\t-L num : optimize paths above this level [default = %d]\n", nLevelMax );
    Abc_Print( -2, "\t-W num : optimize paths falling into this window [default = %d]\n", nTimeWindow );
    Abc_Print( -2, "\t-K num : the number of LUT inputs (LUT size) [default = %d]\n", nLutSize );
    Abc_Print( -2, "\t-C num : the number of cuts at a node [default = %d]\n", nCutNum );
    Abc_Print( -2, "\t-R num : the delay relaxation ratio (num >= 0) [default = %d]\n", nRelaxRatio );
    Abc_Print( -2, "\t-v     : toggle printing verbose information [default = %s]\n", fVerbose? "yes": "no" );
    Abc_Print( -2, "\t-h     : print the command usage\n");
    return 1;
}

