            // if the LUT size is specified, disable library
            pPars.pLutLib = nil;
            break;
        case 'C':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-C\" should be followed by a positive integer.\n" );
                goto usage;
            }
            pPars.nCutsMax = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nCutsMax < 0 {
                goto usage; }
            break;
        case 'F':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-F\" should be followed by a positive integer.\n" );
                goto usage;
            }
            pPars.nFlowIters = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nFlowIters < 0 {
