            }
            pPars.nAreaIters = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nAreaIters < 0 {
                goto usage; }
            break;
        case 'G':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-G\" should be followed by a positive integer no less than 3.\n" );
                goto usage;
            }
            pPars.nGateSize = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nGateSize < 2 {
                goto usage; }
            break;
        case 'R':
            if globalUtilOptind >= argc {
                Abc_Print( 1, "Command line switch \"-R\" should be followed by a floating point number.\n" );
                return 0;
            }
            pPars.nRelaxRatio = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nRelaxRatio < 0 {
