                Abc_Print( -1, "Command line switch \"-X\" should be followed by a positive integer 0,1,or 2.\n" );
                goto usage;
            }
            pPars.nAndDelay = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nAndArea < 0 {
