***********************************************************************/
func Abc_CommandAbc9Dch(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    extern Gia_Man_t * Gia_ManEquivReduce2( Gia_Man_t * p );
    var pTemp *Gia_Man_t;
    var Pars Dch_Pars_t;
    var pPars *Dch_Pars_t = &Pars;
    var c, fMinLevel, fEquiv int32;
    // set defaults
    Dch_ManSetDefaultParams( pPars );
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "WCSsptfremgcxvh" ) ) != -1  {
        switch  c  {
        case 'W':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-W\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nWords = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nWords < 0 {
                goto usage; }
            break;
        case 'C':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-C\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nBTLimit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nBTLimit < 0 {
                goto usage; }
            break;
        case 'S':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-S\" should be followed by an integer.\n" );
                goto usage;
            }
            pPars.nSatVarMax = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if pPars.nSatVarMax < 0 {
                goto usage; }
            break;
        case 's':
            pPars.fSynthesis ^= 1;
            break;
        case 'p':
            pPars.fPower ^= 1;
            break;
        case 't':
            pPars.fSimulateTfo ^= 1;
            break;
        case 'f':
            pPars.fLightSynth ^= 1;
            break;
        case 'r':
            pPars.fSkipRedSupp ^= 1;
            break;
        case 'e':
            fEquiv ^= 1;
            break;
        case 'm':
            fMinLevel ^= 1;
            break;
        case 'g':
            pPars.fUseGia ^= 1;
            break;
        case 'c':
            pPars.fUseCSat ^= 1;
            break;
        case 'x':
            pPars.fUseNew ^= 1;
            break;
        case 'v':
            pPars.fVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    if pAbc.pGia == nil {
        Abc_Print( -1, "Abc_CommandAbc9Dch(): There is no AIG.\n" );
        return 1;
    }
    if Gia_ManBufNum(pAbc.pGia) {
        Abc_Print( -1, "Abc_CommandAbc9Dch(): This command does not work with barrier buffers.\n" );
        return 1;
    }
    if fEquiv != 0 {
        var pNew *Aig_Man_t  = Gia_ManToAigSimple( pAbc.pGia );
        assert(Gia_ManObjNum(pAbc.pGia) == Aig_ManObjNum(pNew), "Gia_ManObjNum(pAbc.pGia) == Aig_ManObjNum(pNew)");
        Dch_ComputeEquivalences( pNew, (Dch_Pars_t *)pPars );
        Gia_ManReprFromAigRepr( pNew, pAbc.pGia );
        Aig_ManStop( pNew );
        pTemp = Gia_ManEquivReduce( pAbc.pGia, 1, 0, 0, 0 );

    } else {
        pTemp = Gia_ManPerformDch( pAbc.pGia, pPars );
        Abc_FrameUpdateGia( pAbc, pTemp );
        if fMinLevel { 
            pTemp = Gia_ManEquivReduce2( pAbc.pGia ); }
    }
    Abc_FrameUpdateGia( pAbc, pTemp );
    return 0;

usage:
    Abc_Print( -2, "usage: &dch [-WCS num] [-sptfremgcxvh]\n" );
    Abc_Print( -2, "\t         computes structural choices using a new approach\n" );
    Abc_Print( -2, "\t-W num : the max number of simulation words [default = %d]\n", pPars.nWords );
    Abc_Print( -2, "\t-C num : the max number of conflicts at a node [default = %d]\n", pPars.nBTLimit );
    Abc_Print( -2, "\t-S num : the max number of SAT variables [default = %d]\n", pPars.nSatVarMax );
    Abc_Print( -2, "\t-s     : toggle synthesizing three snapshots [default = %s]\n", pPars.fSynthesis? "yes": "no" );
    Abc_Print( -2, "\t-p     : toggle power-aware rewriting [default = %s]\n", pPars.fPower? "yes": "no" );
    Abc_Print( -2, "\t-t     : toggle simulation of the TFO classes [default = %s]\n", pPars.fSimulateTfo? "yes": "no" );
    Abc_Print( -2, "\t-f     : toggle using lighter logic synthesis [default = %s]\n", pPars.fLightSynth? "yes": "no" );
    Abc_Print( -2, "\t-r     : toggle skipping choices with redundant support [default = %s]\n", pPars.fSkipRedSupp? "yes": "no" );
    Abc_Print( -2, "\t-e     : toggle computing and merging equivalences [default = %s]\n", fEquiv? "yes": "no" );
    Abc_Print( -2, "\t-m     : toggle minimizing logic level after merging equivalences [default = %s]\n", fMinLevel? "yes": "no" );
    Abc_Print( -2, "\t-g     : toggle using GIA to prove equivalences [default = %s]\n", pPars.fUseGia? "yes": "no" );
    Abc_Print( -2, "\t-c     : toggle using circuit-based SAT vs. MiniSat [default = %s]\n", pPars.fUseCSat? "yes": "no" );
    Abc_Print( -2, "\t-x     : toggle using new choice computation [default = %s]\n", pPars.fUseNew? "yes": "no" );
    Abc_Print( -2, "\t-v     : toggle verbose printout [default = %s]\n", pPars.fVerbose? "yes": "no" );
    Abc_Print( -2, "\t-h     : print the command usage\n");
    return 1;
}


