func Abc_CommandAbc9Undo(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    var c int32;
    // set defaults
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "h" ) ) != -1  {
        switch  c  {
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    if pAbc.pGia == nil {
        Abc_Print( -1, "Abc_CommandAbc9Undo(): There is no design.\n" );
        return 1;
    }
    if pAbc.pGia2 == nil {
        Abc_Print( -1, "Abc_CommandAbc9Undo(): There is no previously saved network.\n" );
        return 1;
    }
    Gia_ManStop( pAbc.pGia );
    pAbc.pGia = pAbc.pGia2;
    pAbc.pGia2 = nil;
    return 0;

usage:
    Abc_Print( -2, "usage: &undo [-h]\n" );
    Abc_Print( -2, "\t        reverses the previous AIG transformation\n" );
    Abc_Print( -2, "\t-h    : print the command usage\n");
    return 1;
}

