    var fBetterQual int32;
    var fDualOut int32;
    var fVerbose int32;
    var fVeryVerbose int32;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "neqdvwh" ) ) != -1  {
        switch  c  {
        case 'n':
            fNewAlgo ^= 1;
            break;
        case 'e':
            fEstimate ^= 1;
            break;
        case 'q':
            fBetterQual ^= 1;
            break;
        case 'd':
            fDualOut ^= 1;
            break;
        case 'v':
            fVerbose ^= 1;
            break;
        case 'w':
            fVeryVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    if pAbc.pGia == nil {
        Abc_Print( -1, "Abc_CommandAbc9Iso(): There is no AIG.\n" );
        return 1;
    }
    if Gia_ManPoNum(pAbc.pGia) == 1 {
        Abc_Print( -1, "Abc_CommandAbc9Iso(): The AIG has only one PO. Isomorphism detection is not performed.\n" );
        return 1;
    }
    if fNewAlgo != 0 {
        pAig = Gia_ManIsoReduce2( pAbc.pGia, &vPosEquivs, nil, fEstimate, fBetterQual, fDualOut, fVerbose, fVeryVerbose );
    } else {
        pAig = Gia_ManIsoReduce( pAbc.pGia, &vPosEquivs, nil, fEstimate, fDualOut, fVerbose, fVeryVerbose ); }
