func Abc_CommandAbc9SplitProve(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    extern int Cec_GiaSplitTest( Gia_Man_t * p, int nProcs, int nTimeOut, int nIterMax, int LookAhead, int fVerbose, int fVeryVerbose, int fSilent );
    var c int32;
    var nProcs int32 = 1;
    var nTimeOut int32 = 10;
    var nIterMax int32;
    var LookAhead int32 = 1;
    var fVerbose int32;
    var fVeryVerbose int32;
    var fSilent int32;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "PTILsvwh" ) ) != -1  {
        switch  c  {
        case 'P':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-P\" should be followed by a positive integer.\n" );
                goto usage;
            }
            nProcs = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nProcs <= 0 {
                goto usage; }
            break;
        case 'T':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-T\" should be followed by a positive integer.\n" );
                goto usage;
            }
            nTimeOut = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nTimeOut <= 0 {
                goto usage; }
            break;
        case 'I':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-I\" should be followed by an integer.\n" );
                goto usage;
            }
            nIterMax = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nIterMax < 0 {
                goto usage; }
            break;
        case 'L':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-L\" should be followed by an integer.\n" );
                goto usage;
            }
            LookAhead = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if LookAhead <= 0 || LookAhead > 100 {
                Abc_Print( -1, "Look-ahead value (\"-L <num>\") should be between 1 and 100.\n", LookAhead );
                goto usage;
            }
            break;
        case 's':
            fSilent ^= 1;
            break;
        case 'v':
            fVerbose ^= 1;
            break;
        case 'w':
            fVeryVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    if pAbc.pGia == nil {
        Abc_Print( -1, "Abc_CommandAbc9SplitProve(): There is no AIG.\n" );
