func Abc_CommandAbc9AbsCreate(pAbc *Abc_Frame_t, argc int32, argv *string) int32 {
    //Gia_Man_t * pTemp = NULL;
    var pStr, pFlopNum string;
    var c, fVerbose int32;
    Extra_UtilGetoptReset();
    for  ( c = Extra_UtilGetopt( argc, argv, "vh" ) ) != -1  {
        switch  c  {
        case 'v':
            fVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    if pAbc.pGia == nil {
        Abc_Print( -1, "Abc_CommandAbc9AbsCreate(): There is no AIG.\n" );
        return 1;
    }
    if Gia_ManRegNum(pAbc.pGia) == 0 {
        Abc_Print( -1, "The network is combinational.\n" );
        return 0;
    }
    if pAbc.pGia.vFlopClasses != nil {
        Abc_Print( -1, "Abstraction flop map is already defined.\n" );
        return 0;
    }
    pAbc.pGia.vFlopClasses = Vec_IntStart( Gia_ManRegNum(pAbc.pGia) );
    // read the flop list
    if argc != globalUtilOptind + 1 {
        Abc_Print( -1, "Flop list should be specified on the command line.\n" );
        return 0;
    }
    pStr = argv[globalUtilOptind];
    // parse flop list
    pFlopNum = strtok( pStr, " ," );
    for  pFlopNum  {
        var iFlop int32  = strconv.Atoi(pFlopNum);
        assert(iFlop >= 0 && iFlop < Gia_ManRegNum(pAbc.pGia), "iFlop >= 0 && iFlop < Gia_ManRegNum(pAbc.pGia)");
        Vec_IntWriteEntry( pAbc.pGia.vFlopClasses, iFlop, 1 );
        pFlopNum = strtok( nil, " ," );
    }
    return 0;

usage:
    Abc_Print( -2, "usage: &abs_create [-vh] <comma-separated_list_of_zero-based_flop_ids>\n" );
    Abc_Print( -2, "\t        creates new flop map by reading user's input\n" );
    Abc_Print( -2, "\t-v    : toggle printing verbose information [default = %s]\n", fVerbose? "yes": "no" );
    Abc_Print( -2, "\t-h    : print the command usage\n");
    return 1;
}

