        case 'A':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-A\" should be followed by an integer.\n" );
                goto usage;
            }
            Algo = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if Algo < 0 {
                goto usage; }
            break;
        case 'K':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-K\" should be followed by an integer.\n" );
                goto usage;
            }
            LutSize = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if LutSize < 0 {
                goto usage; }
            break;
        case 'N':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-N\" should be followed by an integer.\n" );
                goto usage;
            }
            nLuts = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nLuts < 0 {
                goto usage; }
            break;
        case 'D':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-D\" should be followed by an integer.\n" );
                goto usage;
            }
            nLevels = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nLevels < 0 {
                goto usage; }
            break;
        case 'L':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-L\" should be followed by an integer.\n" );
                goto usage;
            }
            Limit = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if Limit < 0 {
                goto usage; }
            break;
        case 'B':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-B\" should be followed by an integer.\n" );
                goto usage;
            }
            nBestTries = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if nBestTries < 0 {
                goto usage; }
            break;
        case 'M':
            if globalUtilOptind >= argc {
                Abc_Print( -1, "Command line switch \"-M\" should be followed by an integer.\n" );
                goto usage;
            }
            Multi = strconv.Atoi(argv[globalUtilOptind]);
            globalUtilOptind++;
            if Multi < 0 {
                goto usage; }
            break;
        case 'x':
            fXor ^= 1;
            break;
        case 'v':
            fVerbose ^= 1;
            break;
        case 'h':
            goto usage;
        default:
            goto usage;
        }
    }
    pTemp = Extra_CommandGen( Algo, LutSize, nLuts, nLevels, Limit, nBestTries, Multi, fXor, fVerbose );
    Abc_FrameUpdateGia( pAbc, pTemp );
    return 0;

usage:
    Abc_Print( -2, "usage: &gen [-AKNDLBMxvh]\n" );
    Abc_Print( -2, "\t          generates network\n" );
    Abc_Print( -2, "\t-A num  : the generation algorithm [default = %d]\n",                 Algo );
    Abc_Print( -2, "\t-K num  : the number of LUT inputs [default = %d]\n",                 LutSize );
    Abc_Print( -2, "\t-N num  : the number of LUTs on one level [default = %d]\n",          nLuts );
    Abc_Print( -2, "\t-D num  : the number of LUT levels [default = %d]\n",                 nLevels );
    Abc_Print( -2, "\t-L num  : limit below which we randomize [default = %d]\n",           Limit );
    Abc_Print( -2, "\t-B num  : select best fanins among this many tries [default = %d]\n", nBestTries );
    Abc_Print( -2, "\t-M num  : the multiplier type (1=array, 2=booth) [default = %d]\n",   Multi );
